-- All fixtures and document metadata below are synthetic and rolled back.
BEGIN;
SET LOCAL statement_timeout='40s';
CREATE TEMP TABLE launch_qa(label text,passed boolean);
GRANT ALL ON launch_qa TO service_role;
SET LOCAL ROLE service_role;
DO $$
DECLARE w uuid;actor uuid;email text;t uuid:=gen_random_uuid();c uuid:=gen_random_uuid();ft uuid:=gen_random_uuid();f uuid;r uuid;u jsonb;claim uuid:=gen_random_uuid();i public.case_participant_invitations;other public.case_participant_invitations;payload jsonb;meta jsonb;op uuid:=gen_random_uuid();blocked boolean;tok jsonb;token_row public.form_tokens;response uuid:=gen_random_uuid();cfg jsonb;creds jsonb;future_case uuid:=gen_random_uuid();private_case uuid:=gen_random_uuid();public_case uuid:=gen_random_uuid();ctx jsonb;capture uuid;proof uuid;capture_hash text;reissued uuid;report jsonb;
BEGIN
 SELECT m.workspace_id,m.user_id INTO w,actor FROM public.workspace_members m JOIN public.workspaces ws ON ws.id=m.workspace_id WHERE m.status='active' AND m.role='owner' AND (m.access_expires_at IS NULL OR m.access_expires_at>now()) AND coalesce((ws.organization_settings#>>'{case_review,separationOfDuties}')::boolean,false)=false LIMIT 1;
 SELECT p.email INTO email FROM public.user_profiles p WHERE id=actor;
 IF w IS NULL OR email IS NULL THEN RAISE EXCEPTION 'QA_NO_WORKSPACE';END IF;
 PERFORM set_config('request.jwt.claim.sub',actor::text,true);
 INSERT INTO public.form_templates(id,workspace_id,name,status,created_by,requires_signature,settings,schema) VALUES(ft,w,'QA PORTAL ROLLBACK','draft',actor,false,'{"requiresSignature":false}','[{"id":"signature","type":"signature_block","required":true}]');
 UPDATE public.form_templates SET status='published' WHERE id=ft;
 payload:=jsonb_build_object('name','QA PORTAL ROLLBACK','description','','case_type','QA','requirements_schema',jsonb_build_object('version',6,'workflowMode','simple','sections',jsonb_build_array(jsonb_build_object('id','section','title','QA','items',jsonb_build_array(jsonb_build_object('id','item','kind','requested_document','title','Documento QA','required',true,'requiresReview',true,'reviewerRole','owner','requiresSignature',false,'allowedFormats',jsonb_build_array('pdf'),'maxSizeMb',15,'allowReplacement',true),jsonb_build_object('id','form','kind','form','title','Formulario QA','sourceId',ft,'sourceVersion','1','sourceRevision',1,'required',true,'requiresReview',false,'requiresSignature',true)))),'verifications','[]'::jsonb,'stages','[]'::jsonb,'reviewPolicy',jsonb_build_object('version',1,'reviewTiming','progressive','approval',jsonb_build_object('enabled',false,'role',null),'completion',jsonb_build_object('mode','manual','role','owner'))),'forms_schema','[]'::jsonb);
 PERFORM public.case_control_publish(t,actor,w,null,payload);
 cfg:=jsonb_build_object('accessMode','public','signatureType','click_sign','requireLiveness',true,'expirationHours',24,'scheduledAt',now()+interval '2 hours','timezone','America/Mazatlan');
 creds:=jsonb_build_array(jsonb_build_object('hash',repeat('1',64),'ciphertext',repeat('x',100),'codeHash',encode(extensions.digest('ABCDEFGH','sha256'),'hex'),'codeCiphertext',repeat('y',100)));
 PERFORM public.case_launch_configured(t,actor,'QA SCHEDULED','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),future_case,email,'[]',creds,'https://example.invalid',cfg);
 IF (SELECT count(*) FROM public.case_invitation_claim(future_case,actor))<>0 OR public.case_invitation_code_claim(future_case,actor)<>'[]'::jsonb THEN RAISE EXCEPTION 'QA_PREMATURE_DELIVERY';END IF;
 blocked:=false;BEGIN PERFORM public.case_portal_context(repeat('1',64),false);EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_INVITATION_NOT_ACTIVE' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_PREMATURE_PORTAL';END IF;
 INSERT INTO launch_qa VALUES('scheduled launch cannot send or open before its UTC delivery time',true);
 PERFORM public.case_cancel_scheduled_launch(future_case,actor);PERFORM public.case_cancel_scheduled_launch(future_case,actor);
 IF (SELECT status FROM public.case_files WHERE id=future_case)<>'cancelled' OR EXISTS(SELECT 1 FROM public.case_participant_invitations WHERE case_file_id=future_case AND revoked_at IS NULL) THEN RAISE EXCEPTION 'QA_SCHEDULE_CANCELLATION';END IF;
 INSERT INTO launch_qa VALUES('cancellation is idempotent and revokes the scheduled invitations',true);
 cfg:=jsonb_build_object('accessMode','private','signatureType','click_sign','requireLiveness',false,'expirationHours',1.0/60,'scheduledAt',null,'timezone','America/Mazatlan','subjectPrefill',jsonb_build_object('nombre','Titular QA','rfc','QA_ONLY'));
 creds:=jsonb_build_array(jsonb_build_object('hash',repeat('2',64),'ciphertext',repeat('x',100)));
 PERFORM public.case_launch_configured(t,actor,'QA PRIVATE','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),private_case,email,'[]',creds,'https://example.invalid',cfg);
 IF NOT (public.case_portal_authorize_actor(repeat('2',64),actor)->>'authorized')::boolean THEN RAISE EXCEPTION 'QA_PRIVATE_ACCOUNT';END IF;
 blocked:=false;BEGIN PERFORM public.case_portal_authorize_actor(repeat('2',64),gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_OTHER_ACCOUNT';END IF;
 SELECT id INTO f FROM public.case_file_forms WHERE case_file_id=private_case;
 tok:=public.case_portal_form_token(repeat('2',64),f);
 IF (SELECT signature_type FROM public.form_tokens WHERE token=tok->>'token')<>'click_sign' THEN RAISE EXCEPTION 'QA_SIGNATURE_NOT_APPLIED';END IF;
 IF (SELECT launch_prefill->>'nombre' FROM public.form_tokens WHERE token=tok->>'token')<>'Titular QA' THEN RAISE EXCEPTION 'QA_PREFILL_NOT_APPLIED';END IF;
 INSERT INTO launch_qa VALUES('private access requires the actual recipient account and carries the selected signature to forms',true);
 cfg:=jsonb_build_object('accessMode','public','signatureType','autografa_digital','requireLiveness',true,'expirationHours',48,'scheduledAt',null,'timezone','America/Mazatlan');
 creds:=jsonb_build_array(jsonb_build_object('hash',repeat('3',64),'ciphertext',repeat('x',100),'codeHash',encode(extensions.digest('ABCDEFGH','sha256'),'hex'),'codeCiphertext',repeat('y',100)));
 PERFORM public.case_launch_configured(t,actor,'QA PUBLIC','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),public_case,email,'[]',creds,'https://example.invalid',cfg);
 PERFORM public.case_launch_configured(t,actor,'QA PUBLIC','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),public_case,email,'[]',creds,'https://example.invalid',cfg);
 IF (SELECT count(*) FROM public.case_invitation_codes k JOIN public.case_participant_invitations inv ON inv.id=k.invitation_id WHERE inv.case_file_id=public_case)<>1 THEN RAISE EXCEPTION 'QA_DUPLICATE_LAUNCH';END IF;
 blocked:=false;BEGIN PERFORM public.case_launch_configured(t,actor,'QA DIFFERENT','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),public_case,email,'[]',creds,'https://example.invalid',cfg);EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_IDEMPOTENCY_CONFLICT' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_CHANGED_LAUNCH';END IF;
 INSERT INTO launch_qa VALUES('retry preserves the case and code, while changed settings cannot reuse the operation',true);
 IF public.case_invitation_code_claim(public_case,actor)<>'[]'::jsonb THEN RAISE EXCEPTION 'QA_CODE_BEFORE_INVITATION';END IF;
 SELECT * INTO i FROM public.case_invitation_claim(public_case,actor);
 PERFORM public.case_invitation_finish(i.id,i.claim_id,'sent','synthetic-provider','PROVIDER_ACCEPTED');
 report:=public.case_invitation_summary(public_case,actor);
 IF report->0->>'status'='sent' OR report->0->>'codeRequired'<>'true' THEN RAISE EXCEPTION 'QA_PARTIAL_MAIL_FALSE_SUCCESS';END IF;
 report:=public.case_invitation_code_claim(public_case,actor);
 IF jsonb_array_length(report)<>1 OR public.case_invitation_code_claim(public_case,actor)<>'[]'::jsonb THEN RAISE EXCEPTION 'QA_CODE_CLAIM';END IF;
 IF public.case_invitation_code_payload(i.id,(report->0->>'claim_id')::uuid,'frozen-code-message')<>public.case_invitation_code_payload(i.id,(report->0->>'claim_id')::uuid,'other-code-message') THEN RAISE EXCEPTION 'QA_CODE_PAYLOAD';END IF;
 PERFORM public.case_invitation_code_finish(i.id,(report->0->>'claim_id')::uuid,'sent','synthetic-code-provider','PROVIDER_ACCEPTED');
 IF public.case_invitation_summary(public_case,actor)->0->>'status'<>'sent' OR public.case_invitation_code_claim(public_case,actor)<>'[]'::jsonb THEN RAISE EXCEPTION 'QA_CODE_DUPLICATE_SEND';END IF;
 INSERT INTO launch_qa VALUES('link and code have independent durable deliveries, leases and frozen messages',true);
 IF public.case_portal_authorize_actor(repeat('3',64),actor)->>'reason'<>'code' THEN RAISE EXCEPTION 'QA_PUBLIC_CODE_SKIPPED';END IF;
 blocked:=false;BEGIN PERFORM public.case_portal_authorize_actor(repeat('3',64),actor,repeat('0',64));EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_BAD_PUBLIC_CODE';END IF;
 IF public.case_portal_authorize_actor(repeat('3',64),actor,encode(extensions.digest('ABCDEFGH','sha256'),'hex'))->>'reason'<>'liveness' THEN RAISE EXCEPTION 'QA_PUBLIC_LIVENESS_SKIPPED';END IF;
 INSERT INTO launch_qa VALUES('public entry requires both the correct code and real scoped biometric evidence',true);
 INSERT INTO public.mobile_upload_sessions(token,user_id,status,expires_at,metadata) VALUES(repeat('4',64),actor,'completed',now()+interval '10 minutes',jsonb_build_object('mode','case_portal_liveness','case_invitation_id',i.id,'identity_match',true,'provider',jsonb_build_object('liveness_passed',true,'face_match',true))) RETURNING id,token_hash INTO capture,capture_hash;
 blocked:=false;BEGIN PERFORM public.case_portal_authorize_actor(repeat('3',64),actor,null,capture_hash);EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_PORTAL_LIVENESS_REQUIRED' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked THEN RAISE EXCEPTION 'QA_FORGED_MOBILE_METADATA';END IF;
 INSERT INTO launch_qa VALUES('editable mobile-session metadata alone cannot manufacture biometric authorization',true);
 INSERT INTO public.id_capture_logs(session_token,user_id,identity_match,nubarium_aprobado,raw_nubarium_response) VALUES(capture_hash,actor,true,true,jsonb_build_object('case_invitation_id',i.id,'liveness_passed',true,'face_match',true)) RETURNING id INTO proof;
 UPDATE public.mobile_upload_sessions SET metadata=metadata||jsonb_build_object('capture_log_id',proof) WHERE id=capture;
 IF NOT (public.case_portal_authorize_actor(repeat('3',64),actor,null,capture_hash)->>'authorized')::boolean THEN RAISE EXCEPTION 'QA_SCOPED_BIOMETRIC_PROOF';END IF;
 INSERT INTO launch_qa VALUES('a service-recorded biometric result grants only its matching invitation and person',true);
 report:=public.case_invitation_portal(repeat('3',64));
 IF NOT coalesce((report#>>'{requirements,0,canSubmit}')::boolean,false) OR NOT coalesce((report#>>'{forms,0,canSubmit}')::boolean,false) THEN RAISE EXCEPTION 'QA_VERIFIED_PORTAL_CONTROLS';END IF;
 SELECT id INTO r FROM public.case_file_requirements WHERE case_file_id=public_case;
 meta:=jsonb_build_object('name','qa-public.pdf','mime','application/pdf','size',1024,'sha256',repeat('c',64),'keyCiphertext','encrypted-test-only','nonce','test-only');
 u:=public.case_portal_prepare_upload(repeat('3',64),r,gen_random_uuid(),meta);
 PERFORM public.case_portal_claim_upload(repeat('3',64),(u->>'id')::uuid,claim,'qa/public-rollback.pdf');
 PERFORM public.case_portal_commit_upload(repeat('3',64),(u->>'id')::uuid,claim);
 PERFORM public.case_portal_commit_upload(repeat('3',64),(u->>'id')::uuid,claim);
 report:=public.case_invitation_portal(repeat('3',64));
 IF report#>>'{requirements,0,status}'<>'uploaded' OR (SELECT count(*) FROM public.case_file_document_versions WHERE case_file_id=public_case)<>1 THEN RAISE EXCEPTION 'QA_PUBLIC_DOCUMENT_RECEIPT';END IF;
 INSERT INTO launch_qa VALUES('verified public portal exposes assigned deliveries and records one document receipt on retry',true);
 SELECT id INTO f FROM public.case_file_forms WHERE case_file_id=public_case;
 tok:=public.case_portal_form_token(repeat('3',64),f);
 SELECT * INTO token_row FROM public.form_tokens WHERE token=tok->>'token';
 IF tok->>'accessMode'<>'public' OR token_row.recipient_user_id<>actor OR token_row.liveness_verified_at IS NULL OR token_row.expires_at>now()+interval '24 hours' THEN RAISE EXCEPTION 'QA_PUBLIC_CHILD_FORM';END IF;
 INSERT INTO launch_qa VALUES('public forms inherit the proven identity and a bounded capability without an account login',true);
 INSERT INTO public.form_responses(token_id,template_id,workspace_id,response_data,field_hashes,respondent_email,respondent_user_id,submitted_at,status) VALUES(token_row.id,ft,w,'{"qa":"public synthetic"}','{}',email,actor,now(),'started') RETURNING id INTO response;
 UPDATE public.form_tokens SET used_at=now() WHERE id=token_row.id;
 UPDATE public.form_responses SET pdf_output_hash=repeat('d',64),status='pdf_generated' WHERE id=response;
 IF NOT EXISTS(SELECT 1 FROM public.case_file_form_submissions WHERE case_form_id=f AND form_response_id=response AND submitted_at IS NOT NULL) THEN RAISE EXCEPTION 'QA_PUBLIC_FORM_RECEIPT';END IF;
 INSERT INTO launch_qa VALUES('a public form receipt binds to its invitation and participant and queues case progress',true);
 report:=public.case_invitation_portal(repeat('3',64));
 IF report#>>'{forms,0,status}'<>'submitted' OR NOT coalesce((report#>>'{forms,0,canResume}')::boolean,false) OR NOT EXISTS(SELECT 1 FROM public.case_file_tasks WHERE case_file_id=public_case AND title='case_runtime:refresh' AND status='pending') THEN RAISE EXCEPTION 'QA_PUBLIC_DELIVERIES_REFRESH';END IF;
 INSERT INTO launch_qa VALUES('the public portal resumes its submitted form and durably requests a case progress refresh',true);


 reissued:=public.case_invitation_manage(public_case,actor,i.id,'renew',gen_random_uuid(),jsonb_build_object('hash',repeat('5',64),'ciphertext',repeat('z',100),'codeHash',encode(extensions.digest('ZZZZZZZZ','sha256'),'hex'),'codeCiphertext',repeat('z',100)));
 blocked:=false;BEGIN PERFORM public.case_portal_authorize_actor(repeat('3',64),actor);EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked OR public.case_portal_authorize_actor(repeat('5',64),actor)->>'reason'<>'code' THEN RAISE EXCEPTION 'QA_RENEWED_ACCESS';END IF;
 INSERT INTO launch_qa VALUES('renewal revokes the old portal and creates a fresh code and authorization scope',true);

 DECLARE signed_type uuid:=gen_random_uuid();signed_case uuid:=gen_random_uuid();part jsonb; BEGIN
  payload:=jsonb_set(payload,'{requirements_schema,sections,0,items,0,requiresSignature}','true');
  PERFORM public.case_control_publish(signed_type,actor,w,null,payload);
  cfg:=jsonb_build_object('accessMode','private','signatureType','click_sign','requireLiveness',false,'expirationHours',24,'scheduledAt',null,'timezone','America/Mazatlan');
  creds:=jsonb_build_array(jsonb_build_object('hash',repeat('6',64),'ciphertext',repeat('x',100)));
  PERFORM public.case_launch_configured(signed_type,actor,'QA SIGNATURE','Titular QA',actor,jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor)),signed_case,email,'[]',creds,'https://example.invalid',cfg);
  SELECT id INTO r FROM public.case_file_requirements WHERE case_file_id=signed_case;
  meta:=jsonb_build_object('name','qa.pdf','mime','application/pdf','size',1024,'sha256',repeat('c',64),'keyCiphertext','encrypted-test-only','nonce','test-only');
  u:=public.case_portal_prepare_upload(repeat('6',64),r,gen_random_uuid(),meta);
  PERFORM public.case_portal_claim_upload(repeat('6',64),(u->>'id')::uuid,claim,'qa/rollback.pdf');
  PERFORM public.case_portal_commit_upload(repeat('6',64),(u->>'id')::uuid,claim);
  SELECT participantes->0 INTO part FROM public.documentos WHERE id=(u->>'document_id')::uuid;
  IF part#>>'{tipoFirma,0}'<>'click_sign' OR part->>'email'<>email THEN RAISE EXCEPTION 'QA_DOCUMENT_SIGNATURE_DEFAULT';END IF;
  INSERT INTO launch_qa VALUES('requested documents receive the participant and selected method without executing a signature',true);
  blocked:=false;BEGIN
   INSERT INTO public.participant_completion_attempts(document_id,document_version_id,participant_reference_id,actor_user_id,action_type,signature_method,idempotency_key) VALUES((u->>'document_id')::uuid,(u->>'version_id')::uuid,gen_random_uuid(),actor,'signature','efirma','qa-wrong-method');
  EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_SIGNATURE_METHOD_UNAVAILABLE' THEN blocked:=true;ELSE RAISE;END IF;END;
  IF NOT blocked THEN RAISE EXCEPTION 'QA_WRONG_METHOD';END IF;
  blocked:=false;BEGIN
   INSERT INTO public.participant_completion_attempts(document_id,document_version_id,participant_reference_id,actor_user_id,action_type,signature_method,idempotency_key) VALUES((u->>'document_id')::uuid,(u->>'version_id')::uuid,gen_random_uuid(),actor,'signature','clicksign','qa-right-method-too-early');
  EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_SIGNATURE_NOT_READY' THEN blocked:=true;ELSE RAISE;END IF;END;
  IF NOT blocked THEN RAISE EXCEPTION 'QA_PREMATURE_SIGNATURE';END IF;
  INSERT INTO launch_qa VALUES('canonical signature claims enforce both the selected method and review/approval prerequisites',true);
 END;
 IF has_function_privilege('authenticated','public.case_launch_configured(uuid,uuid,text,text,uuid,jsonb,uuid,text,jsonb,jsonb,text,jsonb)','EXECUTE') OR has_table_privilege('anon','public.case_invitation_codes','SELECT') OR has_function_privilege('anon','public.case_dispatch_secrets()','EXECUTE') THEN RAISE EXCEPTION 'QA_SECRET_BOUNDARY';END IF;
 INSERT INTO launch_qa VALUES('Data API cannot create launches, read codes or retrieve worker secrets',true);
END;$$;
RESET ROLE;
SELECT * FROM launch_qa;
ROLLBACK;
